using System.Text.Json;
using System.Text.Json.Serialization;
using FitnessFormulasi.Api.Data;
using FitnessFormulasi.Api.Domain;
using Microsoft.EntityFrameworkCore;

namespace FitnessFormulasi.Api.Features.Nutrition;

/// <summary>
/// Loads the built-in food database at startup: products with USDA FoodData Central (SR Legacy) values and the
/// typical recipes of Uzbek dishes (Features/Nutrition/Data, generated by backend/tools/nutrition-data). Rows are
/// matched by key and updated in place, so client data referring to them is never touched.
/// </summary>
public static class NutritionSeeder
{
    private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web) { Converters = { new JsonStringEnumConverter() } };

    private sealed record FoodsFile(string Source, List<FoodRow> Foods);
    private sealed record FoodRow(string Key, int FdcId, string NameRu, string? NameUz, string NameEn, List<string> Aliases,
        FoodCategory Category, bool Per100Ml, Per100Row Per100g);
    private sealed record Per100Row(decimal Kcal, decimal Protein, decimal Fat, decimal Carbs, decimal? Fiber, decimal? Sugar,
        decimal? SaturatedFat, decimal? SodiumMg);
    private sealed record RecipesFile(List<RecipeRow> Recipes);
    private sealed record RecipeRow(string Key, string DishKey, string NameRu, string? NameUz, string? NameEn, List<string> Aliases,
        FoodCategory Category, decimal PortionGrams, decimal? YieldGrams, string? Description, List<RecipeIngredientRow> Ingredients);
    private sealed record RecipeIngredientRow(string Key, decimal Grams, IngredientRole Role);

    public static async Task SeedAsync(AppDbContext db, ILogger logger, CancellationToken ct)
    {
        var foods = Read<FoodsFile>("nutrition/foods.json");
        var recipes = Read<RecipesFile>("nutrition/recipes.json");

        var existing = await db.FoodProducts.Where(p => p.Key != null && p.OwnerClientId == null).ToDictionaryAsync(p => p.Key!, ct);
        var added = 0;
        foreach (var f in foods.Foods)
        {
            if (!existing.TryGetValue(f.Key, out var p))
            {
                p = new FoodProduct { Key = f.Key, Name = f.NameRu };
                db.FoodProducts.Add(p);
                existing[f.Key] = p;
                added++;
            }
            p.Name = f.NameRu;
            p.NameUz = f.NameUz;
            p.NameEn = f.NameEn;
            p.Aliases = f.Aliases;
            p.Category = f.Category;
            p.Per100Ml = f.Per100Ml;
            p.Kcal = f.Per100g.Kcal;
            p.Protein = f.Per100g.Protein;
            p.Fat = f.Per100g.Fat;
            p.Carbs = f.Per100g.Carbs;
            p.Fiber = f.Per100g.Fiber;
            p.Sugar = f.Per100g.Sugar;
            p.SaturatedFat = f.Per100g.SaturatedFat;
            p.SodiumMg = f.Per100g.SodiumMg;
            p.Source = NutritionSource.Usda;
            p.SourceRef = f.FdcId.ToString(System.Globalization.CultureInfo.InvariantCulture);
            p.SearchText = FoodDatabaseService.SearchText(p.Name, null, p.NameEn, p.NameUz, p.Aliases);
        }

        var existingRecipes = await db.FoodRecipes.Include(r => r.Ingredients)
            .Where(r => r.Key != null && r.OwnerClientId == null).ToDictionaryAsync(r => r.Key!, ct);
        foreach (var r in recipes.Recipes)
        {
            if (!existingRecipes.TryGetValue(r.Key, out var recipe))
            {
                recipe = new FoodRecipe { Key = r.Key, Name = r.NameRu };
                db.FoodRecipes.Add(recipe);
                added++;
            }
            recipe.Name = r.NameRu;
            recipe.NameUz = r.NameUz;
            recipe.NameEn = r.NameEn;
            recipe.Aliases = r.Aliases;
            recipe.Category = r.Category;
            recipe.DishKey = r.DishKey;
            recipe.IsTraditional = true;
            recipe.Description = r.Description;
            recipe.PortionGrams = r.PortionGrams;
            recipe.YieldGrams = r.YieldGrams;
            recipe.SearchText = FoodDatabaseService.SearchText(recipe.Name, null, recipe.NameEn, recipe.NameUz, recipe.Aliases);

            var wanted = r.Ingredients.Select((i, n) => (Product: existing[i.Key], i.Grams, i.Role, n)).ToList();
            var same = recipe.Ingredients.Count == wanted.Count && recipe.Ingredients.OrderBy(i => i.SortOrder).Zip(wanted)
                .All(x => x.First.FoodProductId == x.Second.Product.Id && x.First.Grams == x.Second.Grams && x.First.Role == x.Second.Role);
            if (!same)
            {
                db.FoodRecipeIngredients.RemoveRange(recipe.Ingredients);
                recipe.Ingredients.Clear();
                foreach (var w in wanted)
                    recipe.Ingredients.Add(new FoodRecipeIngredient { Product = w.Product, Grams = w.Grams, Role = w.Role, SortOrder = w.n });
            }
            FoodDatabaseService.ApplyPer100(recipe, wanted.Select(w => new FoodAmount(w.Grams, NutritionMath.Nullable(w.Product), 0)));
        }

        var changes = db.ChangeTracker.Entries().Count(e => e.State is EntityState.Added or EntityState.Modified or EntityState.Deleted);
        if (changes == 0) return;
        await db.SaveChangesAsync(ct);
        logger.LogInformation("Food database: {Products} products and {Recipes} traditional recipes loaded ({Added} new, {Changes} rows changed)",
            foods.Foods.Count, recipes.Recipes.Count, added, changes);
    }

    private static T Read<T>(string resource)
    {
        using var stream = typeof(NutritionSeeder).Assembly.GetManifestResourceStream(resource)
                           ?? throw new InvalidOperationException($"Embedded resource {resource} is missing.");
        return JsonSerializer.Deserialize<T>(stream, Json) ?? throw new InvalidOperationException($"{resource} is empty.");
    }
}
